    "faqTitle": "Sıkça Sorulan Sorular",
    "faqQ1": "Match cut nedir?",
    "faqA1": "Match cut, bir ifadenin veya kelimenin hızlı ve senkronize bir şekilde sahne değiştirerek (kesilerek) gösterildiği güçlü bir kurgu tekniğidir.",
    "faqQ2": "Video kaç saniyede hazır olur?",
    "faqA2": "Seçtiğiniz ayarlara göre genelde 15-30 saniye içinde videonuz doğrudan tarayıcınızda hazır hale gelir.",
    "faqQ3": "Ticari projelerde kullanabilir miyim?",
    "faqA3": "Evet, ürettiğiniz videoları tüm kişisel ve ticari projelerinizde hiçbir telif sorunu olmadan kullanabilirsiniz.",
    "faqQ4": "Hangi formatları destekliyor?",
    "faqA4": "Şu anda YouTube için Yatay (16:9) ve TikTok/Reels için Dikey (9:16) formatlarını desteklemekteyiz.",
    "footerDesc": "Tarayıcı tabanlı, profesyonel video kurgu araçları.",
