    "legalContactTitle": "4. คุกกี้และความเป็นส่วนตัวของคุณ",
    "legalContactText": "คุกกี้ที่จำเป็นจะช่วยให้ระบบทำงานได้อย่างปลอดภัย ส่วนคุกกี้วิเคราะห์จะทำงานก็ต่อเมื่อได้รับความยินยอมจากคุณเท่านั้น",
