    "faqTitle": "Perguntas Frequentes (FAQ)",
    "faqQ1": "O que é um Match Cut?",
    "faqA1": "Match Cut é uma técnica cinematográfica em que uma palavra ou cena se mantém no foco enquanto os cenários sincronizados mudam rapidamente.",
    "faqQ2": "Quanto tempo leva para gerar um vídeo?",
