export const t = (key, lang = 'en') => {
  if (strings[lang] && strings[lang][key] !== undefined) {
    return strings[lang][key];
  }
  if (strings['en'] && strings['en'][key] !== undefined) {
    return strings['en'][key];
  }
  return key;
};
